package com.householdfinance.finance.adapter.in.rest;import com.householdfinance.finance.domain.DomainException;import jakarta.servlet.http.HttpServletRequest;import java.net.URI;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(DomainException.class)ProblemDetail domain(DomainException e,HttpServletRequest r){var p=ProblemDetail.forStatusAndDetail(HttpStatus.UNPROCESSABLE_ENTITY,e.getMessage());p.setType(URI.create("https://householdfinance/problems/domain"));p.setProperty("instance",r.getRequestURI());return p;}@ExceptionHandler(Exception.class)ProblemDetail other(Exception e){return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,e.getMessage());}}
